head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 위 또는 아래 버튼을 클릭한다.
    //1. In the browser, click the Up or Down button.
    //Verify 1. 숫자가 변경되면서, oldValue 와 newValue 의 비교팝업이 생성된다.
    //1. As the number is changed, a comparison popup is generated between oldValue and newValue.
    //Up
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('spinner1_upButton').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Down
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('spinner1_downButton').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    spinner1.setValue("1");
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 01-Mar-2018
    window.log = false;
    window.console.log = function() {
        log = true;
    }
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

